import{_ as i,o as s,c as a,a2 as t}from"./chunks/framework.CPzUcv0I.js";const k=JSON.parse('{"title":"Cloud Providers and Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"guide/horizon/providers-and-auth.md","filePath":"guide/horizon/providers-and-auth.md"}'),r={name:"guide/horizon/providers-and-auth.md"};function o(n,e,d,l,h,p){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="cloud-providers-and-authentication" tabindex="-1">Cloud Providers and Authentication <a class="header-anchor" href="#cloud-providers-and-authentication" aria-label="Permalink to &quot;Cloud Providers and Authentication&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Pattern-Provider%20Factory-blue.svg" alt="Pattern"><img src="https://img.shields.io/badge/Providers-Google%20%7C%20Dropbox%20%7C%20OneDrive-green.svg" alt="Providers"><img src="https://img.shields.io/badge/Security-Hardware--Bound%20Tokens-red.svg" alt="Security"></div><p>Gens-Horizon is built to be completely storage agnostic. By utilizing the <strong>Factory</strong> design pattern in <code>provider.js</code>, the engine delegates all network I/O operations to isolated adapters located within the <code>/providers</code> directory.</p><hr><h2 id="_1-provider-factory-pattern-provider-js" tabindex="-1">1. Provider Factory Pattern (<code>provider.js</code>) <a class="header-anchor" href="#_1-provider-factory-pattern-provider-js" aria-label="Permalink to &quot;1. Provider Factory Pattern (`provider.js`)&quot;">​</a></h2><p>Each cloud adapter implements an identical standard interface:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BaseCloudProvider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> login</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {}                           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Launches the OAuth2 authorization flow</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getQuota</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {}                         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Returns { total, used, free }</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> listFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {}                  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Enumerates remote deltas and metadata</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uploadFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">localPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">remoteName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {}  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Uploads with stream chunking</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> downloadFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">remoteName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">destPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {} </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Direct stream download</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> deleteFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">fileId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {}                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Removes remote cloud artifact</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> refreshTokenIfNeeded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {}             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Silently refreshes bearer tokens</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The factory function <code>getProvider(name)</code> dynamically instantiates the appropriate adapter based on settings in <code>horizon_settings.json</code>:</p><ul><li><code>&#39;google&#39;</code> -&gt; <code>providers/google.js</code></li><li><code>&#39;dropbox&#39;</code> -&gt; <code>providers/dropbox.js</code></li><li><code>&#39;onedrive&#39;</code> -&gt; <code>providers/onedrive.js</code></li></ul><hr><h2 id="_2-provider-implementations" tabindex="-1">2. Provider Implementations <a class="header-anchor" href="#_2-provider-implementations" aria-label="Permalink to &quot;2. Provider Implementations&quot;">​</a></h2><h3 id="google-drive-providers-google-js" tabindex="-1">Google Drive (<code>providers/google.js</code>) <a class="header-anchor" href="#google-drive-providers-google-js" aria-label="Permalink to &quot;Google Drive (`providers/google.js`)&quot;">​</a></h3><ul><li>Interfaces directly with Google Drive REST API v3 without heavy external SDK packages.</li><li>Stores game data in an isolated root folder (<code>GensHorizon/</code>) or within private application data storage (<code>appDataFolder</code>).</li><li>Leverages multipart uploads for rapid delta transfer and resumable upload sessions for larger snapshots.</li></ul><h3 id="dropbox-providers-dropbox-js" tabindex="-1">Dropbox (<code>providers/dropbox.js</code>) <a class="header-anchor" href="#dropbox-providers-dropbox-js" aria-label="Permalink to &quot;Dropbox (`providers/dropbox.js`)&quot;">​</a></h3><ul><li>Uses official Dropbox v2 REST endpoints (<code>/2/files/upload</code>, <code>/2/files/download</code>).</li><li>Validates file integrity using Dropbox&#39;s native block-level content hashing.</li><li>Handles short-lived token refreshing seamlessly via standard OAuth2 exchange.</li></ul><h3 id="microsoft-onedrive-providers-onedrive-js" tabindex="-1">Microsoft OneDrive (<code>providers/onedrive.js</code>) <a class="header-anchor" href="#microsoft-onedrive-providers-onedrive-js" aria-label="Permalink to &quot;Microsoft OneDrive (`providers/onedrive.js`)&quot;">​</a></h3><ul><li>Interfaces with the Microsoft Graph API (<code>/me/drive/special/approot</code> or designated subfolders).</li><li>Supports chunked multi-part upload sessions (<code>createUploadSession</code>) to ensure reliability over slower networks.</li></ul><hr><h2 id="_3-resilience-and-adaptive-retries-retry-js" tabindex="-1">3. Resilience and Adaptive Retries (<code>retry.js</code>) <a class="header-anchor" href="#_3-resilience-and-adaptive-retries-retry-js" aria-label="Permalink to &quot;3. Resilience and Adaptive Retries (`retry.js`)&quot;">​</a></h2><p>To withstand transient network interruptions, rate limits (HTTP 429), or temporary server unavailability (HTTP 503), cloud operations are governed by an adaptive retry wrapper:</p><ul><li><strong>Exponential Backoff:</strong> Base delay (<code>retryBaseDelay: 1500 ms</code>) increases exponentially, modulated with random jitter to prevent thundering herd conditions.</li><li><strong>Configurable Attempt Limit:</strong> Configured by default for 3 automatic attempts.</li><li><strong>Fail-Fast for Fatal Errors:</strong> Non-recoverable authorization failures (such as revoked credentials) exit immediately without exhausting API quotas.</li></ul><hr><h2 id="_4-hardware-bound-token-storage-auth-js" tabindex="-1">4. Hardware-Bound Token Storage (<code>Auth.js</code>) <a class="header-anchor" href="#_4-hardware-bound-token-storage-auth-js" aria-label="Permalink to &quot;4. Hardware-Bound Token Storage (`Auth.js`)&quot;">​</a></h2><p>Cloud credentials and OAuth2 refresh tokens are <strong>never stored in plaintext</strong> on disk:</p><ol><li>Upon first execution, Gens-Horizon generates a permanent 256-bit cryptographically secure identifier (<code>crypto.randomBytes(32)</code>) saved to <code>.machine_id</code>.</li><li>A distinct 16-byte random salt is generated in <code>salt.key</code> with restricted file permissions (<code>mode: 0o600</code>).</li><li>A 256-bit symmetric encryption key is derived using <strong>PBKDF2</strong> across 600,000 iterations using the <code>.machine_id</code> as the password.</li><li>Tokens are encrypted using <strong>AES-256-GCM</strong> with a unique 12-byte initialization vector (IV) generated for each write operation.</li></ol><div class="tip custom-block"><p class="custom-block-title">Anti-Theft Protection</p><p>Copying the Gens-Horizon directory to an external drive will not expose stored credentials. Decrypting tokens on another machine is cryptographically impossible without the original host machine&#39;s hardware-bound <code>.machine_id</code>.</p></div>',26)])])}const g=i(r,[["render",o]]);export{k as __pageData,g as default};
